import {mountUIPagesSkin} from './ui-pages-skin.js';
import {PIXEL_PITCH,UI_CELL,UI_PIXELS,floorCell} from './viewer-grid.js';
import {bindVFDChart,formatVFDValue} from './saas-viz.js';
import {SAAS_PAGES,COMPONENT_IDS,FLEET,loadSaasState,saveSaasState,normalizeSaasState,filterFleet,filterInspections,updateInspection,getDashboardData} from './saas-state.js';

const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const palette={mint:'#a9e9df',blue:'#89b9ef',amber:'#ffc782',red:'#f58e84',dim:'#558c7e'};
const pages={overview:['OPERATIONS','Operations overview','A clear view of your fleet, inspection coverage, and work awaiting review.'],fleet:['ASSETS / TELEMETRY','Fleet workspace','Inspect each aircraft, its sensor kit, and its current assignment.'],inspections:['CAPTURE / REVIEW','Inspection queue','Move from captured evidence to a reviewed inspection.'],analytics:['PERFORMANCE / TRENDS','Inspection analytics','Compare inspection output, finding types, and aircraft utilization.'],components:['DESIGN SYSTEM / DATA','Charts & instruments','Reusable instruments. Change a value, select a point, and save edit notes.'],workspace:['WORKSPACE / PREFERENCES','Workspace settings','Shape the workspace and display. Explore the plan for a connected service.']};
const componentInfo={line:['TREND GRAPH','Time-series with point selection and an optional comparison series.'],bar:['BAR GRAPH','Compare categories with labeled, pixel-filled horizontal bars.'],donut:['DISTRIBUTION','A segmented ring for categorical shares and fleet availability.'],gauge:['RADIAL METER','A segmented dial for coverage, battery, or signal strength.'],heatmap:['ACTIVITY MATRIX','Compare activity through an intensity matrix on the display lattice.'],sparkline:['SPARKLINE','A compact trend that fits inside a metric card.'],bullet:['LINEAR METER','Progress against a target, without a full chart axis.']};
const loaded=loadSaasState();let state=loaded.state,skin=null,chartDisposers=[],dialogDisposers=[],returnFocus=null,storageWarning='';
const specs=new Map(),chartApis=new Map();const view={fleetQuery:'',fleetStatus:'all',fleetSort:'id',fleetDirection:1,inspectionQuery:'',inspectionStatus:'all',componentValue:72,comparison:true};
const color=()=>palette[state.chartColor];
const chartMark=()=>({dots:'dots',hash:'hashes',square:'blocks'}[state.chartPattern]);
const statusColor=value=>['high','service'].includes(value)?palette.red:['review','medium','scheduled'].includes(value)?palette.amber:value==='ready'?palette.blue:palette.mint;
const siteLabel=value=>value==='waterfront'?'WATERFRONT':value==='shipyard'?'SHIPYARD':'ALL SITES';
const label=(text,dim=false,extra='')=>`<span data-vfd="label"${dim?' data-vfd-tone="dim"':''} ${extra}>${esc(text)}</span>`;
const button=(text,action,extra='')=>`<button type="button" data-vfd="button" data-action="${action}" ${extra}>${esc(text)}</button>`;
function message(text){$('saas-message').textContent=storageWarning&&text!==storageWarning?storageWarning+' / '+text:text;skin?.refresh();}
function persist(text){const saved=saveSaasState(state);state=saved.state;storageWarning=saved.error||'';message(saved.error||text||'WORKSPACE SAVED ON THIS DEVICE');return !saved.error;}
function download(name,value,mime='application/json'){const content=typeof value==='string'?value:JSON.stringify(value,null,2)+'\n';const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function chart(id,spec,classes=''){specs.set(id,{color:color(),...spec});return `<canvas id="${id}" class="saas-chart ${classes}" data-vfd="canvas" tabindex="0" role="img" aria-label="${esc(spec.title||spec.type+' chart')}"></canvas>`;}
function card(title,body,action='',extra=''){return `<section class="saas-card ${extra}" data-vfd="panel"><div class="saas-card-head"><h2 data-vfd="label">${esc(title)}</h2>${action}</div>${body}</section>`;}
function grid(body,count=2,ratio=''){return `<div class="saas-grid" data-grid="${count}"${ratio?` data-ratio="${ratio}"`:''}>${body}</div>`;}
function readout(id,left,right='SELECT A POINT'){return `<div class="chart-readout">${label(left,false,`id="${id}-readout"`)}${label(right,true)}</div>`;}
function kpi(title,value,caption,id,trend,accent=palette.mint){return `<section class="saas-card saas-kpi" data-vfd="panel">${label(title,true,'class="saas-kpi-title"')}<strong class="saas-kpi-number" data-vfd="label" data-vfd-scale="3" data-vfd-color="${accent}">${esc(value)}</strong><div class="saas-kpi-bottom">${label(caption,true)}${chart(id,{type:'sparkline',title:title+' trend',data:trend,color:accent},'saas-mini-chart')}</div></section>`;}
function bindCharts(root,bag){root.querySelectorAll('canvas[data-vfd=canvas]').forEach(canvas=>{if(!specs.has(canvas.id))return;const id=canvas.id;const api=bindVFDChart(canvas,{getSpec:()=>specs.get(id),onSelect:point=>{const spec=specs.get(id);spec.selectedIndex=point.index;const output=$(id+'-readout');if(output)output.textContent=`${point.label} / ${formatVFDValue(point.value,spec.unit)}`;skin?.refresh();},refresh:()=>skin?.refresh()});chartApis.set(id,api);bag.push(()=>{api.destroy();chartApis.delete(id);});});}
function snapTracks(){for(const el of document.querySelectorAll('[data-grid]')){const requested=Number(el.dataset.grid);const width=el.getBoundingClientRect().width;let count=requested;if(width<UI_CELL*(requested===4?55:48))count=requested===4&&width>=UI_CELL*32?2:1;const cells=Math.max(count,Math.floor(width/UI_CELL+1e-7)-2*(count-1));const ratio=count===2&&el.dataset.ratio==='2:1'?[2,1]:Array(count).fill(1);const total=ratio.reduce((a,b)=>a+b,0);let used=0;el.style.gridTemplateColumns=ratio.map((weight,index)=>{const n=index===count-1?cells-used:Math.floor(cells*weight/total);used+=n;return `${n*UI_CELL}px`;}).join(' ');}}
function layout(){const root=document.documentElement;root.style.setProperty('--surface-width',`${floorCell(innerWidth)}px`);root.style.setProperty('--pixel',`${PIXEL_PITCH}px`);root.style.setProperty('--cell',`${UI_CELL}px`);document.body.dataset.pixelPitch=PIXEL_PITCH;document.body.dataset.uiPixels=UI_PIXELS;snapTracks();if(innerWidth<=640){const nav=$('saas-nav'),cells=Math.floor(nav.clientWidth/UI_CELL)-2,base=Math.floor(cells/3);nav.style.gridTemplateColumns=[base,base,cells-base*2].map(n=>`${n*UI_CELL}px`).join(' ');}else $('saas-nav').style.removeProperty('grid-template-columns');skin?.relayout();}
function disposeCharts(){chartDisposers.forEach(dispose=>dispose());chartDisposers=[];specs.clear();}
function render(){disposeCharts();const [eyebrow,title,description]=pages[state.page];$('page-eyebrow').textContent=eyebrow;$('page-title').textContent=title;$('page-description').textContent=description;$('workspace-name').textContent=state.workspaceName;$('workspace-shortcut').textContent=state.workspaceName;$('heading-action').hidden=['components','workspace'].includes(state.page);$('scope-toolbar').hidden=['components','workspace'].includes(state.page);$('period-buttons').hidden=!['overview','analytics'].includes(state.page);$('site-filter').value=state.site;$('scope-caption').textContent='AS OF 23 NOV 2026 / DEMO';document.querySelectorAll('[data-range]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.range===state.range)));document.querySelectorAll('[data-page]').forEach(el=>{el.setAttribute('aria-current',el.dataset.page===state.page?'page':'false');});const host=$('saas-content');({overview:renderOverview,fleet:renderFleet,inspections:renderInspections,analytics:renderAnalytics,components:renderComponents,workspace:renderWorkspace}[state.page])(host);bindCharts(host,chartDisposers);layout();skin?.refresh();document.title=`${title} / Phosphor`;}
function navigate(page,{history=true}={}){if(!SAAS_PAGES.includes(page))page='overview';closeDetail();state.page=page;persist();render();if(history){const url=new URL(location.href);url.searchParams.set('page',page);if(url.href!==location.href)window.history.pushState(null,'',url);}window.scrollTo({top:0,behavior:'instant'});message(`${pages[page][1]} / DEMO WORKSPACE`);}

function renderOverview(host){const d=getDashboardData({...state,state}),m=d.metrics;const queue=filterInspections(state,{site:state.site,status:'review'}).slice(0,3);
  host.innerHTML=grid(kpi('INSPECTIONS',m.inspections,'COMPLETED IN PERIOD','kpi-inspections',d.volume)+kpi('COVERAGE',m.coverage+'%','AVERAGE SCAN COVERAGE','kpi-coverage',d.coverageTrend)+kpi('AIRCRAFT ACTIVE',`${m.activeDrones} / ${m.totalDrones}`,'CURRENT DEMO SNAPSHOT','kpi-active',d.utilization,palette.blue)+kpi('AWAITING REVIEW',m.reviewQueue,'CURRENT DEMO QUEUE','kpi-review',d.defects,palette.amber),4)
    +grid(card('INSPECTION VOLUME',chart('volume',{type:'line',title:'Inspection volume',data:d.volume,unit:' SCANS'})+readout('volume',`${m.inspections} INSPECTIONS / ${d.rangeLabel}`),label(d.rangeLabel,true))+card('FLEET AVAILABILITY',chart('availability',{type:'donut',title:'Fleet availability',data:d.fleetStatus})+readout('availability',`${m.readyDrones} READY / ${m.serviceDrones} SERVICE`,'CURRENT SNAPSHOT'),button('FLEET','page','data-target="fleet"')),2,'2:1')
    +grid(card('REVIEW NEXT',queue.length?`<div class="saas-action-list">${queue.map(item=>`<article class="saas-action-item"><div><h3 data-vfd="label">${esc(item.title)}</h3><p data-vfd="label" data-vfd-color="${statusColor(item.severity)}">${item.findings} FINDINGS / ${item.severity.toUpperCase()} PRIORITY</p></div>${button('REVIEW','inspection',`data-id="${item.id}"`)}</article>`).join('')}</div>`:`<p class="saas-note" data-vfd="label">ALL INSPECTIONS REVIEWED. YOUR QUEUE IS CLEAR.</p>`,button('ALL WORK','page','data-target="inspections"'))+card('SCAN COVERAGE',chart('coverage',{type:'gauge',title:'Average scan coverage',value:m.coverage,max:100,target:95,unit:'%'},'short')+readout('coverage','TARGET / 95%','PERIOD AVERAGE')),2,'2:1')
    +`<section class="saas-callout" data-vfd="panel"><div><h2 data-vfd="label">FROM SIGNAL TO SURFACE</h2><p data-vfd="label" data-vfd-tone="dim">OPEN THE 3D LAB TO INSPECT SPLATS, HOLOGRAM MAPS, AND THE DRONE CONTROL CLUSTER.</p></div><a href="./viewer.html" data-vfd="button">OPEN 3D LAB</a></section>`;
}
function renderFleet(host){const fleet=filterFleet({site:state.site});const active=fleet.filter(d=>d.status==='active').length;const average=Math.round(fleet.reduce((sum,d)=>sum+d.battery,0)/(fleet.length||1));
  host.innerHTML=grid(card('AIRCRAFT IN SERVICE',`<strong class="saas-kpi-number" data-vfd="label" data-vfd-scale="3">${fleet.length}</strong>${label('ASSIGNED TO '+siteLabel(state.site),true)}`)+card('ACTIVE MISSIONS',`<strong class="saas-kpi-number" data-vfd="label" data-vfd-scale="3" data-vfd-color="${palette.blue}">${active}</strong>${label('SIMULATED TELEMETRY',true)}`)+card('AVERAGE BATTERY',chart('fleet-energy',{type:'bullet',title:'Fleet average battery',value:average,max:100,target:30,unit:'%'},'meter')),3)
    +card('AIRCRAFT DIRECTORY',`<div class="table-controls"><input id="fleet-search" type="search" data-vfd="search" placeholder="SEARCH AIRCRAFT" aria-label="Search aircraft" value="${esc(view.fleetQuery)}"><select id="fleet-status" data-vfd="select" aria-label="Aircraft status"><option value="all">ALL STATUSES</option><option value="active">ACTIVE</option><option value="ready">READY</option><option value="service">SERVICE</option></select>${label('',true,'id="fleet-count"')}</div><div class="saas-table-scroll"><table class="saas-table"><thead><tr><th>${button('AIRCRAFT','sort-fleet','data-sort="id"')}</th><th>${label('ASSIGNMENT',true)}</th><th>${label('STATUS',true)}</th><th>${button('BATTERY','sort-fleet','data-sort="battery"')}</th><th>${label('FLIGHT HRS',true)}</th><th>${label('DETAIL',true)}</th></tr></thead><tbody id="fleet-rows"></tbody></table></div>`)
    +`<p class="saas-note" data-vfd="label" data-vfd-tone="dim">THIS WORKSPACE SHOWS DEMO AIRCRAFT. THE 3D LAB HAS A SEPARATE SIMULATED DRONE; NO REAL VEHICLE IS CONNECTED.</p>`;
  $('fleet-status').value=view.fleetStatus;fillFleetTable();$('fleet-search').addEventListener('input',event=>{view.fleetQuery=event.target.value;fillFleetTable();});$('fleet-status').addEventListener('change',event=>{view.fleetStatus=event.target.value;fillFleetTable();});
}
function fillFleetTable(){const list=filterFleet({query:view.fleetQuery,site:state.site,status:view.fleetStatus}).sort((a,b)=>view.fleetDirection*(view.fleetSort==='battery'?a.battery-b.battery:a.id.localeCompare(b.id)));$('fleet-count').textContent=`${list.length} AIRCRAFT`;$('fleet-rows').innerHTML=list.map(d=>`<tr><td>${label(d.id+' / '+d.name)}${label(siteLabel(d.site),true,'class="table-subtitle"')}</td><td>${label(d.mission)}</td><td>${label(d.status,false,`data-vfd-color="${statusColor(d.status)}"`)}</td><td>${label(d.battery+'%')}</td><td>${label(d.flightHours.toFixed(1)+' H')}</td><td>${button('VIEW','drone',`data-id="${d.id}" aria-label="View ${d.name}"`)}</td></tr>`).join('')||`<tr><td colspan="6" class="empty-cell">${label('NO AIRCRAFT MATCH. CLEAR THE SEARCH OR CHANGE YOUR FILTER.')}</td></tr>`;document.querySelectorAll('[data-sort]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.sort===view.fleetSort)));skin?.refresh();}
function renderInspections(host){const list=filterInspections(state,{site:state.site});host.innerHTML=grid(['review','approved','scheduled'].map(status=>card(status==='review'?'AWAITING REVIEW':status.toUpperCase(),`<strong class="saas-kpi-number" data-vfd="label" data-vfd-scale="3" data-vfd-color="${statusColor(status)}">${list.filter(x=>x.status===status).length}</strong>${label(status==='review'?'READY FOR A HUMAN DECISION':status==='approved'?'REVIEW COMPLETE':'UPCOMING DEMO CAPTURES',true)}`)).join(''),3)+card('INSPECTION REGISTER',`<div class="table-controls"><input id="inspection-search" type="search" data-vfd="search" placeholder="SEARCH INSPECTIONS" aria-label="Search inspections" value="${esc(view.inspectionQuery)}"><select id="inspection-status" data-vfd="select" aria-label="Inspection status"><option value="all">ALL STATUSES</option><option value="review">AWAITING REVIEW</option><option value="approved">APPROVED</option><option value="scheduled">SCHEDULED</option></select>${label('',true,'id="inspection-count"')}</div><div class="saas-table-scroll"><table class="saas-table"><thead><tr>${['INSPECTION / ASSET','PRIORITY','COVERAGE','FINDINGS','STATUS','OPEN'].map(x=>`<th>${label(x,true)}</th>`).join('')}</tr></thead><tbody id="inspection-rows"></tbody></table></div>`)+`<p class="saas-note" data-vfd="label" data-vfd-tone="dim">REVIEW DECISIONS AND NOTES SAVE LOCALLY. EXPORT THE WORKSPACE TO KEEP OR HAND OFF THESE EDITS.</p>`;fillInspectionTable();$('inspection-status').value=view.inspectionStatus;$('inspection-search').addEventListener('input',event=>{view.inspectionQuery=event.target.value;fillInspectionTable();});$('inspection-status').addEventListener('change',event=>{view.inspectionStatus=event.target.value;fillInspectionTable();});}
function fillInspectionTable(){const list=filterInspections(state,{site:state.site,query:view.inspectionQuery,status:view.inspectionStatus});$('inspection-count').textContent=`${list.length} INSPECTIONS`;$('inspection-rows').innerHTML=list.map(item=>`<tr><td>${label(item.title)}${label(item.id+' / '+siteLabel(item.site),true,'class="table-subtitle"')}</td><td>${label(item.severity,false,`data-vfd-color="${statusColor(item.severity)}"`)}</td><td>${label(item.coverage+'%')}</td><td>${label(item.findings)}</td><td>${label(item.status==='review'?'IN REVIEW':item.status,false,`data-vfd-color="${statusColor(item.status)}"`)}</td><td>${button('OPEN','inspection',`data-id="${item.id}" aria-label="Open ${item.id}"`)}</td></tr>`).join('')||`<tr><td colspan="6" class="empty-cell">${label('NO INSPECTIONS MATCH THESE FILTERS.')}</td></tr>`;skin?.refresh();}
function renderAnalytics(host){const d=getDashboardData({...state,state});host.innerHTML=grid(kpi('FLIGHT HOURS',d.metrics.flightHours.toFixed(1),'IN SELECTED PERIOD','analytics-hours',d.utilization,palette.blue)+kpi('FINDINGS',d.metrics.findings,'ACROSS ALL CATEGORIES','analytics-findings',d.defects,palette.amber)+kpi('AVERAGE COVERAGE',d.metrics.coverage+'%','CAPTURE COMPLETENESS','analytics-coverage',d.coverageTrend),3)+card('COVERAGE OVER TIME',`<div class="legend-row">${label('SCAN COVERAGE',false,`data-vfd-color="${color()}"`)}${view.comparison?label('TARGET / 95%',false,`data-vfd-color="${palette.amber}"`):''}</div>${chart('analytics-trend',{type:'line',title:'Coverage over time',data:d.coverageTrend,max:100,unit:'%',series:view.comparison?[{label:'TARGET',color:palette.amber,values:d.coverageTrend.map(()=>95)}]:[]})}${readout('analytics-trend',d.rangeLabel,'SELECT TO INSPECT')}`,button('TARGET','compare',`aria-pressed="${view.comparison}"`))+grid(card('FINDING TYPES',chart('defect-bars',{type:'bar',title:'Finding types',data:d.defects,unit:' FINDINGS'})+readout('defect-bars',d.metrics.findings+' FINDINGS'))+card('AIRCRAFT UTILIZATION',chart('utilization-bars',{type:'bar',title:'Aircraft flight hours',data:d.utilization,color:palette.blue,unit:' H'})+readout('utilization-bars',d.metrics.flightHours+' FLIGHT HOURS')),2)+grid(card('ACTIVITY MATRIX',chart('activity',{type:'heatmap',title:'Capture activity by day',data:d.heatmap,columns:7,unit:' CAPTURES'},'short')+readout('activity','RECENT 35-DAY SAMPLE','LOW / HIGH'))+card('REPORT SNAPSHOT',`<div class="saas-detail-values" data-grid="2"><div>${label('PERIOD',true)}<strong data-vfd="label">${esc(d.rangeLabel)}</strong></div><div>${label('SITE',true)}<strong data-vfd="label">${siteLabel(state.site)}</strong></div><div>${label('INSPECTIONS',true)}<strong data-vfd="label">${d.metrics.inspections}</strong></div><div>${label('FINDINGS',true)}<strong data-vfd="label">${d.metrics.findings}</strong></div></div><p class="saas-note" data-vfd="label" data-vfd-tone="dim">EXPORT THE EXACT VALUES BEHIND THE CURRENT REPORT. SAMPLE DATA, NOT AN OPERATIONAL REPORT.</p>${button('EXPORT CSV','export-csv')}`),2);}
function componentSpec(type){const d=getDashboardData({...state,state});const common={type,title:componentInfo[type][0],color:color(),value:view.componentValue,max:100,target:85,unit:'%'};if(type==='line')return {...common,data:d.coverageTrend.map((x,i)=>({...x,value:Math.max(0,Math.min(100,x.value-30+view.componentValue/3))}))};if(type==='bar')return {...common,max:undefined,unit:'',data:d.defects.map(({label,value})=>({label,value}))};if(type==='donut')return {...common,unit:'',data:d.fleetStatus.map((p,i)=>({...p,color:[color(),palette.dim,palette.blue][i]}))};if(type==='heatmap')return {...common,unit:'',data:d.heatmap,columns:7};if(type==='sparkline')return {...common,unit:'',data:d.volume};return common;}
function renderComponents(host){const type=state.selectedComponent;host.innerHTML=`<div class="component-picker" role="group" aria-label="Chart components">${COMPONENT_IDS.map(id=>button(id.toUpperCase(),'component',`data-type="${id}" aria-pressed="${id===type}"`)).join('')}</div>`+grid(card(componentInfo[type][0],`<p class="saas-note" data-vfd="label" data-vfd-tone="dim">${esc(componentInfo[type][1])}</p><div class="component-preview">${chart('component-live',componentSpec(type))}</div>${readout('component-live',['gauge','bullet'].includes(type)?'USE THE VALUE SLIDER':'POINTER OR ARROW KEYS','LIVE COMPONENT')}`)+card('MODIFY THIS INSTRUMENT',`<div class="component-settings"><label class="field"><span id="component-value-label" data-vfd="label">VALUE / ${view.componentValue}%</span><input id="component-value" type="range" data-vfd="slider" min="0" max="100" value="${view.componentValue}" aria-label="Instrument value" ${['gauge','bullet','line'].includes(type)?'':'disabled'}></label><label class="field"><span data-vfd="label">SIGNAL COLOR</span><select id="component-color" data-vfd="select"><option value="mint">PHOSPHOR MINT</option><option value="blue">ION BLUE</option><option value="amber">WARM AMBER</option></select></label><label class="field"><span data-vfd="label">DISPLAY PATTERN</span><select id="component-pattern" data-vfd="select"><option value="dots">DOTS</option><option value="hash">HASHES</option><option value="square">SQUARES</option></select></label><label class="field"><span data-vfd="label">EDIT NOTE / ${type.toUpperCase()}</span><textarea id="component-note" maxlength="4000" data-vfd="search" aria-label="Instrument edit note" placeholder="DESCRIBE THE NEXT EDIT">${esc(state.componentNotes[type]||'')}</textarea></label>${button('SAVE NOTE','save-component-note')}${button('EXPORT SPEC','export-component')}</div>`),2,'2:1')+card('USE IN YOUR PROGRAM',`<p class="saas-note component-copy" data-vfd="label" data-vfd-tone="dim">IMPORT THE SHARED CHART PAINTER. THE CANVAS DRAWS INTO THE SAME VFD COMPOSITOR AS THE REST OF THE APP.</p><pre class="component-code" data-vfd="label" data-vfd-case="preserve">import { bindVFDChart } from './saas-viz.js';\nbindVFDChart(canvas, { getSpec: () =&gt; spec, refresh: () =&gt; skin.refresh() });</pre><div class="saas-row wrap"><a href="./handoff/SAAS-PLAN.md" data-vfd="button">PRODUCT PLAN</a><a href="./handoff/SAAS-COMPONENTS.md" data-vfd="button">CHART API</a><a href="./ui-pages.html" data-vfd="button">PAGE ATLAS</a></div>`);
  $('component-color').value=state.chartColor;$('component-pattern').value=state.chartPattern;
  $('component-value').addEventListener('input',event=>{view.componentValue=Number(event.target.value);$('component-value-label').textContent=`VALUE / ${view.componentValue}%`;specs.set('component-live',componentSpec(type));chartApis.get('component-live')?.refresh();});
  $('component-color').addEventListener('change',event=>{state.chartColor=event.target.value;persist('SIGNAL COLOR SAVED');specs.set('component-live',componentSpec(type));chartApis.get('component-live')?.refresh();});
  $('component-pattern').addEventListener('change',event=>{state.chartPattern=event.target.value;persist('DISPLAY PATTERN SAVED');skin?.refresh();});
  $('component-note').addEventListener('input',event=>{state.componentNotes[type]=event.target.value;persist('COMPONENT NOTE SAVED');});
}
function renderWorkspace(host){host.innerHTML=grid(card('WORKSPACE PROFILE',`<form id="workspace-form" class="saas-form"><label class="field"><span data-vfd="label">WORKSPACE NAME</span><input name="workspaceName" data-vfd="search" type="text" maxlength="64" required value="${esc(state.workspaceName)}"></label><label class="field"><span data-vfd="label">TELEMETRY UNITS</span><select name="unit" data-vfd="select"><option value="metric">METRIC / M</option><option value="imperial">IMPERIAL / FT</option></select></label><div class="saas-toggle-row"><div>${label('REVIEW NOTIFICATIONS')}<p data-vfd="label" data-vfd-tone="dim">PREFERENCE FOR THE CONNECTED PILOT.</p></div>${button(state.notifications?'ON':'OFF','toggle-pref',`data-pref="notifications" aria-pressed="${state.notifications}"`)}</div><div class="saas-toggle-row"><div>${label('WEEKLY DIGEST')}<p data-vfd="label" data-vfd-tone="dim">SAVED PREFERENCE. NO EMAILS ARE SENT.</p></div>${button(state.digest?'ON':'OFF','toggle-pref',`data-pref="digest" aria-pressed="${state.digest}"`)}</div><button data-vfd="button" type="submit">SAVE WORKSPACE</button></form>`)+card('DISPLAY LAYERS',`<div class="saas-form">${[['brightness','BRIGHTNESS',20,200],['glow','BLOOM',0,100],['contrast','CONTRAST',50,220],['grid','CELL MASK',0,100]].map(([key,title,min,max])=>`<label class="field"><span id="display-${key}-label" data-vfd="label">${title} / ${state[key]}%</span><input data-setting="${key}" type="range" data-vfd="slider" min="${min}" max="${max}" value="${state[key]}" aria-label="${title}"></label>`).join('')}<p class="saas-settings-note" data-vfd="label" data-vfd-tone="dim">ONE PIXEL GRID ACROSS PANELS, TYPE, AND CHARTS. THESE SETTINGS ARE SAVED FOR THE SAAS WORKSPACE.</p></div>`),2)+grid(card('ACCESS MODEL / PLANNED',`<div class="member-row">${label('OPERATOR')}${label('CAPTURE / FLEET',true)}</div><div class="member-row">${label('REVIEWER')}${label('FINDINGS / APPROVAL',true)}</div><div class="member-row">${label('ADMIN')}${label('ACCESS / WORKSPACE',true)}</div><p class="saas-settings-note" data-vfd="label" data-vfd-tone="dim">ROLE MANAGEMENT, INVITES, AND ORGANIZATION ACCOUNTS REQUIRE THE CONNECTED SERVICE. THIS PROTOTYPE HAS LOCAL STATE ONLY.</p>`)+card('USAGE / DEMO BUDGET',chart('storage-budget',{type:'bullet',title:'Example workspace storage usage',value:38,max:100,target:80,unit:' GB'},'meter')+readout('storage-budget','38 / 100 GB','ILLUSTRATIVE')+`<p class="saas-settings-note" data-vfd="label" data-vfd-tone="dim">A PLACE FOR STORAGE, CAPTURE HOURS, AND PROCESSING QUOTAS. NO PLAN OR BILLING IS ACTIVE.</p><a href="./handoff.html" data-vfd="button">BACK UP WORKSPACE</a>`),2)+card('PRODUCT PLAN',`<ol class="phase-list"><li><h3 data-vfd="label" data-vfd-color="${palette.mint}">NOW / INTERACTIVE PROTOTYPE</h3><p data-vfd="label" data-vfd-tone="dim">OVERVIEW, FLEET, INSPECTIONS, ANALYTICS, REUSABLE INSTRUMENTS, AND LOCAL SETTINGS. ONE SHARED RENDER SYSTEM.</p></li><li><h3 data-vfd="label" data-vfd-color="${palette.blue}">NEXT / CONNECTED PILOT</h3><p data-vfd="label" data-vfd-tone="dim">ADD IDENTITY, WORKSPACE RECORDS, CAPTURE UPLOADS, PROCESSING JOBS, AND READ-ONLY TELEMETRY ADAPTERS.</p></li><li><h3 data-vfd="label" data-vfd-color="${palette.amber}">LATER / MULTI-TENANT SERVICE</h3><p data-vfd="label" data-vfd-tone="dim">ENFORCE ROLES AND TENANT ISOLATION. ADD AUDIT HISTORY, RETENTION, COLLABORATION, QUOTAS, AND BILLING.</p></li></ol><a href="./handoff/SAAS-PLAN.md" data-vfd="button">READ FULL PLAN</a>`);
  $('workspace-form').elements.unit.value=state.unit;$('workspace-form').addEventListener('submit',event=>{event.preventDefault();const form=new FormData(event.currentTarget);state=normalizeSaasState({...state,workspaceName:form.get('workspaceName'),unit:form.get('unit')});if(persist('WORKSPACE PROFILE SAVED')){$('workspace-name').textContent=state.workspaceName;$('workspace-shortcut').textContent=state.workspaceName;}skin?.refresh();});
  host.querySelectorAll('[data-setting]').forEach(input=>input.addEventListener('input',()=>{state[input.dataset.setting]=Number(input.value);const names={brightness:'BRIGHTNESS',glow:'BLOOM',contrast:'CONTRAST',grid:'CELL MASK'};$(`display-${input.dataset.setting}-label`).textContent=`${names[input.dataset.setting]} / ${input.value}%`;skin?.setOptics({brightness:state.brightness,glow:state.glow,contrast:state.contrast,grid:state.grid});persist('DISPLAY SETTING SAVED');}));
}

function openDetail(title,content){closeDetail();returnFocus=document.activeElement;$('detail-title').textContent=title;$('detail-content').innerHTML=content;$('detail-dialog').show();$('detail-dialog').setAttribute('aria-modal','true');$('ui-shell').inert=true;bindCharts($('detail-content'),dialogDisposers);layout();$('close-detail').focus();}
function closeDetail(){dialogDisposers.forEach(dispose=>dispose());dialogDisposers=[];if($('detail-dialog').open){$('detail-dialog').close();$('ui-shell').inert=false;returnFocus?.focus();}skin?.relayout();}
function openDrone(id){const d=FLEET.find(d=>d.id===id);if(!d)return;const altitude=state.unit==='imperial'?`${Math.round(d.altitude*3.28084)} FT`:`${d.altitude} M`;openDetail(d.id+' / '+d.name,`<p class="dialog-description" data-vfd="label" data-vfd-tone="dim">${esc(d.mission)} / ${siteLabel(d.site)} / DEMO TELEMETRY</p><div class="saas-detail-values" data-grid="2"><div>${label('STATUS',true)}<strong data-vfd="label" data-vfd-color="${statusColor(d.status)}">${d.status.toUpperCase()}</strong></div><div>${label('ALTITUDE',true)}<strong data-vfd="label">${altitude}</strong></div><div>${label('FLIGHT TIME',true)}<strong data-vfd="label">${d.flightHours} H</strong></div><div>${label('SENSOR KIT',true)}<strong data-vfd="label">${esc(d.sensor)}</strong></div></div>${grid(card('BATTERY',chart('drone-battery',{type:'gauge',title:d.name+' battery',value:d.battery,max:100,target:30,unit:'%'},'short'))+card('LINK QUALITY',chart('drone-signal',{type:'gauge',title:d.name+' signal strength',value:d.signal,max:100,target:70,color:palette.blue,unit:'%'},'short')),2)}<p class="saas-settings-note" data-vfd="label" data-vfd-tone="dim">THE 3D LAB OPENS THE EXISTING SIMULATION. THIS DIRECTORY ENTRY IS DEMO DATA AND IS NOT BOUND TO A LIVE AIRCRAFT.</p><div class="dialog-actions"><a href="./viewer.html" data-vfd="button">OPEN 3D LAB</a>${button('INSPECTIONS','drone-inspections',`data-id="${d.id}"`)}</div>`);}
function openInspection(id){const item=filterInspections(state).find(x=>x.id===id);if(!item)return;openDetail(item.id+' / INSPECTION',`<p class="dialog-description" data-vfd="label">${esc(item.title)} / ${esc(item.asset)}</p><div class="saas-detail-values" data-grid="2"><div>${label('AIRCRAFT',true)}<strong data-vfd="label">${item.droneId}</strong></div><div>${label('CAPTURE DATE',true)}<strong data-vfd="label">${item.date}</strong></div><div>${label('PRIORITY',true)}<strong data-vfd="label" data-vfd-color="${statusColor(item.severity)}">${item.severity.toUpperCase()}</strong></div><div>${label('FINDINGS',true)}<strong data-vfd="label">${item.findings} / DEMO FINDINGS</strong></div></div>${chart('inspection-coverage',{type:'bullet',title:'Inspection coverage',value:item.coverage,max:100,target:95,unit:'%'},'meter')}<form id="review-form" class="saas-form"><label class="field"><span data-vfd="label">REVIEW STATUS</span><select name="status" data-vfd="select"><option value="review">AWAITING REVIEW</option><option value="approved">APPROVED</option><option value="scheduled">SCHEDULED</option></select></label><label class="field"><span data-vfd="label">REVIEW NOTE</span><textarea name="note" data-vfd="search" maxlength="4000" placeholder="ADD YOUR REVIEW OR FOLLOW-UP">${esc(item.note)}</textarea></label><button type="submit" data-vfd="button">SAVE REVIEW</button></form><p class="saas-settings-note" data-vfd="label" data-vfd-tone="dim">REVIEW CHANGES SAVE TO THIS BROWSER. CONNECTED EVIDENCE AND TEAM REVIEW ARE PLANNED.</p>`);$('review-form').elements.status.value=item.status;$('review-form').addEventListener('submit',event=>{event.preventDefault();const form=new FormData(event.currentTarget);state=updateInspection(state,id,{status:form.get('status'),note:form.get('note')});const ok=persist();closeDetail();render();message(ok?`REVIEW SAVED / ${id}`:'REVIEW KEPT IN SESSION / BROWSER STORAGE UNAVAILABLE');});skin?.refresh();}

$('saas-nav').innerHTML=Object.keys(pages).map((id,index)=>`${index===4?label('WORKSPACE TOOLS',true,'class="nav-separator"'):''}<button data-page="${id}" data-vfd="button">${id==='components'?'INSTRUMENTS':id==='workspace'?'SETTINGS':id.toUpperCase()}</button>`).join('');
$('saas-nav').addEventListener('click',event=>{const target=event.target.closest('[data-page]');if(target)navigate(target.dataset.page);});
$('workspace-shortcut').addEventListener('click',()=>navigate('workspace'));
$('site-filter').addEventListener('change',event=>{state.site=event.target.value;persist();render();message('SITE / '+siteLabel(state.site));});
$('period-buttons').addEventListener('click',event=>{const target=event.target.closest('[data-range]');if(target){state.range=target.dataset.range;persist();render();message('REPORTING PERIOD / '+state.range.toUpperCase());}});
$('export-workspace').addEventListener('click',()=>{download('phosphor-saas-workspace.json',{format:'phosphor-saas-workspace',version:1,demo:true,state});message('WORKSPACE SETTINGS AND REVIEW NOTES EXPORTED');});
$('close-detail').addEventListener('click',closeDetail);$('detail-dialog').addEventListener('cancel',event=>{event.preventDefault();closeDetail();});
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const action=target.dataset.action;
  if(action==='page')navigate(target.dataset.target);
  if(action==='drone')openDrone(target.dataset.id);
  if(action==='inspection')openInspection(target.dataset.id);
  if(action==='drone-inspections'){view.inspectionQuery=target.dataset.id;view.inspectionStatus='all';state.site='all';navigate('inspections');}
  if(action==='sort-fleet'){view.fleetDirection=view.fleetSort===target.dataset.sort?-view.fleetDirection:1;view.fleetSort=target.dataset.sort;fillFleetTable();}
  if(action==='compare'){view.comparison=!view.comparison;render();document.querySelector('[data-action=compare]')?.focus();}
  if(action==='component'){state.selectedComponent=target.dataset.type;persist();render();document.querySelector('[data-type='+state.selectedComponent+']')?.focus();}
  if(action==='save-component-note'){state.componentNotes[state.selectedComponent]=$('component-note').value;persist('EDIT NOTE SAVED / '+state.selectedComponent.toUpperCase());}
  if(action==='export-component'){download(`phosphor-${state.selectedComponent}.json`,{format:'phosphor-chart-spec',version:1,spec:specs.get('component-live'),renderer:{module:'ui-pages-skin.js',pattern:chartMark(),pixelPitch:PIXEL_PITCH,uiPixels:UI_PIXELS,optics:{brightness:state.brightness,glow:state.glow,contrast:state.contrast,grid:state.grid,refraction:0}},note:state.componentNotes[state.selectedComponent]||''});message('CHART SPECIFICATION EXPORTED');}
  if(action==='toggle-pref'){state[target.dataset.pref]=!state[target.dataset.pref];target.setAttribute('aria-pressed',String(state[target.dataset.pref]));target.textContent=state[target.dataset.pref]?'ON':'OFF';persist('PREFERENCE SAVED / NO NOTIFICATIONS SENT');}
  if(action==='export-csv'){const d=getDashboardData({...state,state});const rows=[['series','period','site','label','value'],...['volume','coverageTrend','defects','utilization'].flatMap(key=>d[key].map(x=>[key,state.range,state.site,x.label,x.value]))];download('phosphor-analytics.csv',rows.map(row=>row.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv');message('CURRENT ANALYTICS EXPORTED AS CSV');}
});
document.addEventListener('keydown',event=>{if(!$('detail-dialog').open||document.querySelector('.grid-select-menu'))return;if(event.key==='Escape'){event.preventDefault();closeDetail();return;}if(event.key==='Tab'){const controls=[...$('detail-dialog').querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.addEventListener('resize',layout);
window.addEventListener('popstate',()=>navigate(new URL(location.href).searchParams.get('page')||'overview',{history:false}));
const requestedPage=new URL(location.href).searchParams.get('page');if(SAAS_PAGES.includes(requestedPage))state.page=requestedPage;
render();skin=mountUIPagesSkin({getState:()=>({mark:chartMark(),optics:{brightness:state.brightness,contrast:state.contrast,grid:state.grid,glow:state.glow,refraction:0}})});layout();message(loaded.error||'DEMO WORKSPACE / SAVED ON THIS DEVICE');
window.addEventListener('pagehide',event=>{if(!event.persisted){disposeCharts();dialogDisposers.forEach(dispose=>dispose());skin?.destroy();}});
